static const clip_t CLIPS[CLIP_COUNT] = {
    [CLIP_CELEBRATE] = {"celebrate", CELEBRATE, sizeof(CELEBRATE) / sizeof(CELEBRATE[0]), false},
    [CLIP_FIREFLY_GULP] = {"firefly_gulp", FIREFLY_GULP, sizeof(FIREFLY_GULP) / sizeof(FIREFLY_GULP[0]), false},
    [CLIP_GREET_BACK] = {"greet_back", GREET_BACK, sizeof(GREET_BACK) / sizeof(GREET_BACK[0]), false},
    [CLIP_KNOCK_GLASS] = {"knock_glass", KNOCK_GLASS, sizeof(KNOCK_GLASS) / sizeof(KNOCK_GLASS[0]), false},
    [CLIP_SNEEZE] = {"sneeze", SNEEZE, sizeof(SNEEZE) / sizeof(SNEEZE[0]), false},
    [CLIP_STARTLE] = {"startle", STARTLE, sizeof(STARTLE) / sizeof(STARTLE[0]), false},
    [CLIP_SULK_TURN] = {"sulk_turn", SULK_TURN, sizeof(SULK_TURN) / sizeof(SULK_TURN[0]), false},
    [CLIP_THINK] = {"think", THINK, sizeof(THINK) / sizeof(THINK[0]), false},
    [CLIP_WAKE_STRETCH] = {"wake_stretch", WAKE_STRETCH, sizeof(WAKE_STRETCH) / sizeof(WAKE_STRETCH[0]), false},
    [CLIP_YAWN] = {"yawn", YAWN, sizeof(YAWN) / sizeof(YAWN[0]), false},
};

const clip_t *clips_get(clip_id_t id)
{
    if (id <= CLIP_NONE || id >= CLIP_COUNT) {
        return NULL;
    }
    return &CLIPS[id];
}

clip_id_t clips_find(const char *name)
{
    for (int i = CLIP_NONE + 1; i < CLIP_COUNT; i++) {
        if (name != NULL && strcmp(name, CLIPS[i].name) == 0) {
            return (clip_id_t) i;
        }
    }
    return CLIP_NONE;
}
